import unittest
import mock
from mock import patch
from selenium.webdriver.common.by import By
from taf.ul.oam.selenium_coam.pages.menu import Menu


class Test_Menu(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.WebDriver')
    def setUp(self, mock_webdriver):
        self.webdriver = mock.MagicMock()
        mock_webdriver.return_value = self.webdriver
        self.menu = Menu()
        self.menu_list = ['BTS Status', 'Site Runtime View', 'Site View']

    def test_open_page(self):
        self.webdriver.driver = mock.Mock()
        self.menu._is_page_active = mock.Mock(return_value=False)
        self.menu.click_enabled_element_after_visible = mock.Mock()
        self.menu.click_enabled_element = mock.Mock()
        self.menu.check_pop_up_window = mock.Mock()
        self.menu.perform_element_hover_by_xpath = mock.Mock()

        self.menu.open_page(self.menu_list)
        self.menu._is_page_active.assert_called_once()
        self.menu.click_enabled_element_after_visible.assert_called()
        self.menu.check_pop_up_window.assert_called_once()
        self.menu.perform_element_hover_by_xpath.assert_called()
        self.menu.click_enabled_element.assert_called_once()

    def test_is_page_active_with_three_level_directory(self):
        timeout = 1
        self.menu.get_text_by_xpath = mock.Mock(return_value='Site View')
        self.menu.check_if_exists = mock.Mock(return_value=True)

        output = self.menu._is_page_active(self.menu_list)
        self.menu.check_if_exists.assert_called_once_with((By.XPATH, self.menu._ACTIVE_TAB_XPATH), timeout=timeout)
        self.menu.get_text_by_xpath.assert_called_once_with(self.menu._ACTIVE_TAB_XPATH)
        self.assertEqual(output, True)

    def test_is_page_active_with_two_level_directory(self):
        timeout = 1
        menu_list = ['aaa', 'bbb']
        self.menu.get_text_by_xpath = mock.Mock(return_value=menu_list[1])
        self.menu.check_if_exists = mock.Mock(return_value=False)

        output = self.menu._is_page_active(menu_list)
        self.menu.check_if_exists.assert_called_once_with((By.XPATH, self.menu._ACTIVE_TAB_XPATH), timeout=timeout)
        self.menu.get_text_by_xpath.assert_called_once_with(self.menu._ACTIVE_TITLE_XPATH)
        self.assertEqual(output, True)

    @patch('taf.ul.oam.selenium_coam.pages.menu.ValidationErrorsModal')
    def test_check_pop_up_window(self, mock_validation_errors_modal):
        sub_menu = "Configuration Management"
        validation_errors_modal = mock_validation_errors_modal.return_value

        self.menu.check_pop_up_window(sub_menu)
        validation_errors_modal.wait_until_validation_errors_modal.assert_called_once()
        validation_errors_modal.close.assert_called_once()
